  expect(Interval.fromDateTimes(invalidDate, validDate).invalidReason).toBe(
    "missing or invalid start"
  );

  expect(Interval.fromDateTimes(validDate.plus({ days: 1 }), validDate).invalidReason).toBe(
    "end before start"
