// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
export function objToLocalTS(obj) {
  // for legacy reasons, Date.UTC interprets years 0-99 as 19XX. Shift those years
  // forward by 400 first, because the Gregorian calendar repeats exactly every 400
  // years, so the leap years (and therefore any day/month overflow) stay correct.
  // Fixing up the resulting year instead would corrupt dates that overflow past
  // February, since e.g. 2000 is a leap year but 100 is not.
  const yearShift = obj.year >= 0 && obj.year < 100 ? 400 : 0;

  let d = Date.UTC(
    obj.year + yearShift,
    obj.month - 1,
    obj.day,
    obj.hour,
    obj.minute,
    obj.second,
    obj.millisecond
  );

  if (yearShift !== 0) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - yearShift);
  }
  return +d;
}

